package com.dramastudio.service;
import com.dramastudio.engine.DagValidator; import com.dramastudio.entity.*; import com.dramastudio.repository.*; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class WorkflowService {
 private final WorkflowRepository workflows;private final WorkflowVersionRepository versions;private final ProjectService projects;private final ProjectService normalizer;private final ObjectMapper json;private final DagValidator validator;
 public WorkflowService(WorkflowRepository w,WorkflowVersionRepository v,ProjectService p,ObjectMapper j,DagValidator d){workflows=w;versions=v;projects=p;normalizer=p;json=j;validator=d;}
 public Workflow owned(String id,String user){Workflow w=workflows.findById(id).filter(x->x.deletedAt==null).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工作流不存在"));projects.getOwned(w.projectId,user);return w;}
 public Map<String,Object> detail(String id,String user){Workflow w=owned(id,user);return Map.of("id",w.id,"projectId",w.projectId,"name",w.name,"status",w.status,"revision",w.revision,"canvas",parse(w.canvasJson));}
 @Transactional public Workflow save(String id,long revision,String name,Map<String,Object> canvas,String user){Workflow w=owned(id,user);if(w.revision!=revision)throw new ResponseStatusException(HttpStatus.CONFLICT,"REVISION_CONFLICT");w.name=name==null?w.name:name;w.canvasJson=write(canvas);Workflow saved=workflows.saveAndFlush(w);normalizer.normalize(saved);return saved;}
 public List<DagValidator.Issue> validate(String id,String user){return validator.validate(parse(owned(id,user).canvasJson));}
 @Transactional public WorkflowVersion publish(String id,String user){Workflow w=owned(id,user);var issues=validator.validate(parse(w.canvasJson));if(!issues.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"工作流校验失败: "+issues.get(0).message());WorkflowVersion v=new WorkflowVersion();v.id=UUID.randomUUID().toString();v.workflowId=w.id;v.versionNo=++w.latestVersionNo;v.snapshotJson=w.canvasJson;v.checksum=sha(v.snapshotJson);v.publishedBy=user;v.createdAt=Instant.now().toString();versions.save(v);w.status="PUBLISHED";workflows.save(w);return v;}
 public WorkflowVersion latestOrPublish(String id,String user){Workflow w=owned(id,user);return versions.findFirstByWorkflowIdOrderByVersionNoDesc(id).filter(v->v.checksum.equals(sha(w.canvasJson))).orElseGet(()->publish(id,user));}
 private Map<String,Object> parse(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalArgumentException(e);}}private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException(e);}}private String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
